<?php
/** Theme setup. */
defined( 'ABSPATH' ) || exit;
function nytt01_setup() { load_theme_textdomain( 'nolan-young-theme-template-01', get_template_directory() . '/languages' ); add_theme_support( 'automatic-feed-links' ); add_theme_support( 'title-tag' ); add_theme_support( 'post-thumbnails' ); add_theme_support( 'responsive-embeds' ); add_theme_support( 'align-wide' ); add_theme_support( 'wp-block-styles' ); add_theme_support( 'appearance-tools' ); add_theme_support( 'customize-selective-refresh-widgets' ); add_theme_support( 'editor-styles' ); add_theme_support( 'html5', array( 'comment-form', 'comment-list', 'gallery', 'caption', 'style', 'script', 'navigation-widgets', 'search-form' ) ); add_theme_support( 'custom-logo', array( 'height' => 80, 'width' => 280, 'flex-height' => true, 'flex-width' => true ) ); register_nav_menus( array( 'primary' => __( 'Primary Navigation', 'nolan-young-theme-template-01' ), 'footer' => __( 'Footer Navigation', 'nolan-young-theme-template-01' ) ) ); add_image_size( 'nytt01-card', 720, 480, true ); }
add_action( 'after_setup_theme', 'nytt01_setup' );
add_action( 'after_setup_theme', function () { $GLOBALS['content_width'] = (int) apply_filters( 'nytt01_content_width', 760 ); }, 0 );
function nytt01_register_sidebars() { register_sidebar( array( 'name' => __( 'Footer Widgets', 'nolan-young-theme-template-01' ), 'id' => 'footer-widgets', 'before_widget' => '<section id="%1$s" class="nytt01-footer-widget %2$s">', 'after_widget' => '</section>', 'before_title' => '<h2 class="nytt01-footer-widget__title">', 'after_title' => '</h2>' ) ); }
add_action( 'widgets_init', 'nytt01_register_sidebars' );
